public class OwnerFieldsDto {

  private String firstName;

  private String lastName;

  private @Nullable String title;

  private @Nullable String address;

  private @Nullable String addressLine1;

  private @Nullable String addressLine2;

  private String city;

  private @Nullable String postcode;

  private String telephone;

  private @Nullable String email;

  @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
  private @Nullable LocalDate registrationDate;

  @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
  private @Nullable LocalDate birthDate;

  private @Nullable Boolean sharesHousehold;

  public OwnerFieldsDto() {
    super();
  }

  /**
   * Constructor with only required parameters
   */
  public OwnerFieldsDto(String firstName, String lastName, String city, String telephone) {
    this.firstName = firstName;
    this.lastName = lastName;
    this.city = city;
    this.telephone = telephone;
  }

  public OwnerFieldsDto firstName(String firstName) {
    this.firstName = firstName;
    return this;
  }

  /**
   * The first name of the pet owner.
   * @return firstName
   */
  @NotNull @Pattern(regexp = "^[\\p{L}]+([ '-][\\p{L}]+){0,2}$") @Size(min = 1, max = 30) 
  @Schema(name = "firstName", example = "George", description = "The first name of the pet owner.", requiredMode = Schema.RequiredMode.REQUIRED)
  @JsonProperty("firstName")
  public String getFirstName() {
    return firstName;
  }
